import crypto from 'crypto';
import fs from 'fs';
import path from 'path';
import { spawnSync } from 'child_process';

const TEMP = process.env.TEMP;
const DIR = path.join(TEMP, 'zentao-6932');
const H = { 'zhi-project-id': 'suzhufang' };
const pass = fs.readFileSync(path.join(TEMP, 'e2e_pass.txt'), 'utf8').trim();
const solver = 'C:\\Users\\Administrator\\.dsh\\skills\\captcha-recognizer\\scripts\\solve-captcha.mjs';

function enc(pl) {
  const k = Buffer.from('A-16-Byte-keyValA-16-Byte-keyVal');
  const iv = Buffer.from('A-16-Byte-String');
  const c = crypto.createCipheriv('aes-256-cbc', k, iv);
  return Buffer.concat([c.update(pl), c.final()]).toString('base64');
}

function solveCap(capPath) {
  const r = spawnSync(process.execPath, [solver, capPath, '--json'], { encoding: 'utf8', timeout: 70000 });
  if (r.status !== 0) throw new Error('solver fail: ' + (r.stderr || r.stdout || '').slice(0, 300));
  const m = r.stdout.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('solver no json: ' + r.stdout.slice(0, 200));
  return JSON.parse(m[0]);
}

async function attempt(i) {
  const c = await (await fetch('http://127.0.0.1:8101/v2.0/code', { headers: H })).json();
  const capPath = path.join(DIR, `cap${i}.jpg`);
  fs.writeFileSync(capPath, Buffer.from(c.data, 'base64'));
  const s = solveCap(capPath);
  console.log(`[try ${i}] uuid=${c.uuid} cap=${capPath} answer=${s.answer} raw=${s.raw} conf=${s.confidence}`);
  if (!s.answer) throw new Error('empty answer');
  const body = { username: 'zsbase', password: enc(pass), code: String(s.answer), uuid: c.uuid };
  const lr = await (await fetch('http://127.0.0.1:8101/v2.0/security/auth/userLogin', {
    method: 'POST', headers: { 'Content-Type': 'application/json', ...H }, body: JSON.stringify(body)
  })).json();
  const token = lr?.data?.accessToken || lr?.accessToken || (typeof lr?.data === 'string' ? lr.data : null);
  console.log(`[try ${i}] login code=${lr.code} msg=${lr.msg} tokenHead=${token ? token.slice(0, 24) : 'NONE'}`);
  if (token) {
    fs.writeFileSync(path.join(DIR, 'token.txt'), token);
    console.log('LOGIN_OK token=' + token);
    return true;
  }
  return false;
}

(async () => {
  for (let i = 1; i <= 4; i++) {
    try { if (await attempt(i)) return; }
    catch (e) { console.log(`[try ${i}] ERR ${e.message}`); }
  }
  console.log('LOGIN_FAILED');
  process.exit(1);
})();

